    await Promise.all(keys.map((key) => this.storage.delete(key)));

    this.events.emit("invalidate", { pattern: `tag:${tag}`, count });
  }

  /**
   * Invalidate all keys with any of the specified tags
   */
  async invalidateByTags(tags: string[]): Promise<void> {
    await Promise.all(tags.map((tag) => this.invalidateByTag(tag)));
  }

  /**
   * Invalidate all keys matching a pattern
   */
  async invalidateByPattern(pattern: string | RegExp): Promise<void> {
    const allKeys = await this.storage.keys();
    const matchingKeys = filterByPattern(allKeys, pattern);
    const count = matchingKeys.length;

    await Promise.all(matchingKeys.map((key) => this.storage.delete(key)));

    const patternStr = pattern instanceof RegExp ? pattern.source : pattern;
    this.events.emit("invalidate", { pattern: patternStr, count });
  }

  /**
   * Touch a key to update its last access time
   */
  async touch(key: string): Promise<void> {
    const fullKey = this.getFullKey(key);
    const value = await this.storage.get(fullKey);

    if (value !== undefined) {
      const metadata = await this.storage.getMetadata(fullKey);
      if (metadata) {
        metadata.lastAccess = Date.now();
        await this.storage.set(fullKey, value, metadata);
      }
    }
  }

  /**
   * Get entries matching a pattern
   */
  async entries(options?: {
    pattern?: string;
    limit?: number;
  }): Promise<Array<{ key: string; value: T }>> {
    const keys = await this.keys(options?.pattern);
    const limitedKeys = options?.limit ? keys.slice(0, options.limit) : keys;

    const entries: Array<{ key: string; value: T }> = [];

    for (const key of limitedKeys) {
      const value = await this.get(key);
      if (value !== undefined) {
        entries.push({ key, value });
      }
    }

    return entries;
  }

  /**
   * Get cache statistics
   */
  async getStats(): Promise<CacheStats> {
    const size = await this.size();

    // Get memory usage if using memory storage
    let memoryUsage: number | undefined;
    if (this.storage instanceof MemoryStorage) {
      memoryUsage = this.storage.getMemoryUsage();
    }

    return this.stats.getStats(size, memoryUsage);
  }

  /**
   * Register an event listener
   */
  on(event: string, handler: EventHandler): void {
    this.events.on(event, handler);
  }

  /**
   * Unregister an event listener
   */
  off(event: string, handler: EventHandler): void {
    this.events.off(event, handler);
  }

  /**
   * Get the full key with namespace
   */
  private getFullKey(key: string): string {
    return this.namespace ? `${this.namespace}:${key}` : key;
  }

  /**
   * Create storage backend based on type
   */
  private createStorage(
    type: StorageType,
    config: CacheFnConfig
  ): StorageBackend<T> {
    switch (type) {
      case "memory":
        return new MemoryStorage<T>({
          maxSize: config.maxSize,
          onEviction: (key, reason) => {
            this.stats.recordEviction();
            this.events.emit("eviction", { key, reason });
          },
        });

      case "indexeddb":
        return new IndexedDBStorage<T>({
          name: config.name,
        });

      default:
        throw new Error(`Unknown storage type: ${type}`);
    }
  }
}
/**
 * Function memoization
 */

import type {
  MemoizeOptions,
  MemoizedFunction,
  CacheStats,
} from "../core/types.js";
import { CacheFn } from "../core/cache.js";
import { generateKey } from "../utils/hash.js";

/**
 * Memoize a function with caching
 */
export function memoize<T extends (...args: any[]) => any>(
  fn: T,
  options?: MemoizeOptions<T>
): T & MemoizedFunction {
  // Create a dedicated cache instance for this function
  const cache = new CacheFn({
    name: `memoize-${fn.name || "anonymous"}`,
    storage: options?.storage ?? "memory",
    maxSize: options?.maxSize ?? 1000,
    defaultTTL: options?.ttl,
  });

  // Default key generator
  const keyGenerator =
    options?.keyGenerator ??
    ((...args: any[]) => {
      return generateKey(fn.name || "fn", args);
    });

  // Create the memoized function
  const memoized = async function (
    this: any,
    ...args: Parameters<T>
  ): Promise<ReturnType<T>> {
    const key = keyGenerator(...args);

    // Try to get from cache
    const cached = await cache.get(key);
    if (cached !== undefined) {
      return cached;
    }

    // Call the original function
    const result = await fn.apply(this, args);

    // Store in cache
    await cache.set(key, result, { tags: options?.tags });

    return result;
  };

  // Attach cache control methods
  memoized.clear = async () => {
    await cache.clear();
  };

  memoized.delete = async (...args: Parameters<T>) => {
    const key = keyGenerator(...args);
    await cache.delete(key);
  };

  memoized.stats = async (): Promise<CacheStats> => {
    return await cache.getStats();
  };

  return memoized as T & MemoizedFunction;
}

/**
 * Synchronous memoization (wraps async memoize but returns sync function)
 */
export function memoizeSync<T extends (...args: any[]) => any>(
  fn: T,
  options?: MemoizeOptions<T>
): T & MemoizedFunction {
  const asyncMemoized = memoize(
    async (...args: Parameters<T>) => fn(...args),
    options
  );

  const syncMemoized = function (
    this: any,
    ...args: Parameters<T>
  ): ReturnType<T> {
    // For sync functions, we need to use a sync cache approach
    // This is a simplified version that uses a Map
    const key = (
      options?.keyGenerator ??
      ((...args: any[]) => generateKey(fn.name || "fn", args))
    )(...args);

    // Use a simple Map for sync memoization
    if (!syncMemoized._cache) {
      syncMemoized._cache = new Map();
    }

    if (syncMemoized._cache.has(key)) {
      return syncMemoized._cache.get(key);
    }

    const result = fn.apply(this, args);
    syncMemoized._cache.set(key, result);

    // Apply max size limit
    const maxSize = options?.maxSize ?? 1000;
    if (syncMemoized._cache.size > maxSize) {
      const firstKey = syncMemoized._cache.keys().next().value;
      syncMemoized._cache.delete(firstKey);
    }

    return result;
  } as any;

  syncMemoized._cache = new Map();

  syncMemoized.clear = async () => {
    syncMemoized._cache.clear();
  };

  syncMemoized.delete = async (...args: Parameters<T>) => {
    const key = (
      options?.keyGenerator ??
      ((...args: any[]) => generateKey(fn.name || "fn", args))
    )(...args);
    syncMemoized._cache.delete(key);
  };

  syncMemoized.stats = async (): Promise<CacheStats> => {
    return {
      hits: 0,
      misses: 0,
      hitRate: 0,
      sets: syncMemoized._cache.size,
      deletes: 0,
      evictions: 0,
      size: syncMemoized._cache.size,
    };
  };

  return syncMemoized as T & MemoizedFunction;
}
/**
 * In-memory storage backend with LRU eviction
 */

import type { CacheEntry } from "../core/types.js";
import type { StorageBackend, EntryMetadata } from "./storage-interface.js";
import { LRUList } from "../strategies/lru-eviction.js";
import { isExpired } from "../strategies/ttl-manager.js";
import { filterByPattern } from "../utils/pattern.js";
import { estimateSize } from "../utils/serialize.js";

export interface MemoryStorageConfig {
  maxSize?: number;
  onEviction?: (key: string, reason: string) => void;
}

/**
 * Memory storage implementation with LRU eviction
 */
export class MemoryStorage<T = any> implements StorageBackend<T> {
  private cache: Map<string, CacheEntry<T>> = new Map();
  private lru: LRUList<string> = new LRUList();
  private tagIndex: Map<string, Set<string>> = new Map();
  private keyTags: Map<string, Set<string>> = new Map();
  private maxSize: number;
  private onEviction?: (key: string, reason: string) => void;

  constructor(config: MemoryStorageConfig = {}) {
    this.maxSize = config.maxSize ?? 1000;
    this.onEviction = config.onEviction;
  }

  async get(key: string): Promise<T | undefined> {
    const entry = this.cache.get(key);

    if (!entry) {
      return undefined;
    }

    // Check if expired
    if (isExpired(entry)) {
      await this.delete(key);
      return undefined;
    }

    // Update access metadata
    entry.hits++;
    entry.lastAccess = Date.now();
    this.lru.touch(key);

    return entry.value;
  }

  async set(key: string, value: T, metadata: EntryMetadata): Promise<void> {
    // Evict if at capacity and key doesn't exist
    if (!this.cache.has(key) && this.cache.size >= this.maxSize) {
      await this.evictLRU();
    }

    // Remove old tags if updating existing entry
    if (this.cache.has(key)) {
      await this.removeAllTagsForKey(key);
    }

    const entry: CacheEntry<T> = {
      key,
      value,
      createdAt: metadata.createdAt,
      expiresAt: metadata.expiresAt,
      tags: metadata.tags,
      hits: metadata.hits,
      lastAccess: metadata.lastAccess,
    };

    this.cache.set(key, entry);
    this.lru.touch(key);

    // Update tag index
    if (metadata.tags) {
      for (const tag of metadata.tags) {
        await this.addTag(tag, key);
      }
    }
  }

  async has(key: string): Promise<boolean> {
    const entry = this.cache.get(key);
    if (!entry) {
      return false;
    }

    if (isExpired(entry)) {
      await this.delete(key);
      return false;
    }

    return true;
  }

  async delete(key: string): Promise<boolean> {
    const entry = this.cache.get(key);
    if (!entry) {
      return false;
    }

    this.cache.delete(key);
    this.lru.remove(key);
    await this.removeAllTagsForKey(key);

    return true;
  }

  async clear(): Promise<void> {
    this.cache.clear();
    this.lru.clear();
    this.tagIndex.clear();
    this.keyTags.clear();
  }

  async keys(pattern?: string): Promise<string[]> {
    const allKeys = Array.from(this.cache.keys());

    // Filter out expired keys
    const validKeys: string[] = [];
    for (const key of allKeys) {
      if (await this.has(key)) {
        validKeys.push(key);
      }
    }

    return filterByPattern(validKeys, pattern);
  }

  async size(): Promise<number> {
    // Clean up expired entries first
    const allKeys = Array.from(this.cache.keys());
    for (const key of allKeys) {
      const entry = this.cache.get(key);
      if (entry && isExpired(entry)) {
        await this.delete(key);
      }
    }

    return this.cache.size;
  }

  async getKeysByTag(tag: string): Promise<string[]> {
    const keys = this.tagIndex.get(tag);
    if (!keys) {
      return [];
    }

    // Filter out expired or deleted keys
    const validKeys: string[] = [];
    for (const key of keys) {
      if (await this.has(key)) {
        validKeys.push(key);
      } else {
        // Clean up stale tag reference
        keys.delete(key);
      }
    }

    return validKeys;
  }

  async addTag(tag: string, key: string): Promise<void> {
    // Update tag index
    if (!this.tagIndex.has(tag)) {
      this.tagIndex.set(tag, new Set());
    }
    this.tagIndex.get(tag)!.add(key);

    // Update key tags
    if (!this.keyTags.has(key)) {
      this.keyTags.set(key, new Set());
    }
    this.keyTags.get(key)!.add(tag);
  }

  async removeTag(tag: string, key: string): Promise<void> {
    // Remove from tag index
    const keys = this.tagIndex.get(tag);
    if (keys) {
      keys.delete(key);
      if (keys.size === 0) {
        this.tagIndex.delete(tag);
      }
    }

    // Remove from key tags
    const tags = this.keyTags.get(key);
    if (tags) {
      tags.delete(tag);
      if (tags.size === 0) {
        this.keyTags.delete(key);
      }
    }
  }

  async getTagsForKey(key: string): Promise<string[]> {
    const tags = this.keyTags.get(key);
    return tags ? Array.from(tags) : [];
  }

  async getMetadata(key: string): Promise<EntryMetadata | undefined> {
    const entry = this.cache.get(key);
    if (!entry) {
      return undefined;
    }

    if (isExpired(entry)) {
      await this.delete(key);
      return undefined;
    }

    return {
      createdAt: entry.createdAt,
      expiresAt: entry.expiresAt,
      tags: entry.tags,
      hits: entry.hits,
      lastAccess: entry.lastAccess,
    };
  }

  /**
   * Get estimated memory usage in bytes
   */
  getMemoryUsage(): number {
    let total = 0;
    for (const entry of this.cache.values()) {
      total += estimateSize(entry.value);
      total += entry.key.length * 2;
    }
    return total;
  }

  /**
   * Evict the least recently used entry
   */
  private async evictLRU(): Promise<void> {
    const key = this.lru.evictLRU();
    if (key) {
      await this.delete(key);
      this.onEviction?.(key, "lru");
    }
  }

  /**
   * Remove all tags for a key
   */
  private async removeAllTagsForKey(key: string): Promise<void> {
    const tags = await this.getTagsForKey(key);
    for (const tag of tags) {
      await this.removeTag(tag, key);
    }
  }
}
"}

